    drawArrow() {
      this.drawControl.drawArrowLine(
        { customData: "someData" },
        (drawnFeature) => {
          console.log("Arrow line created:", drawnFeature);
        },
        { size: "10%", frequency: "endonly" }
      );
    },

    testDrawArrow() {
      var group2offsetx = 0.6;
      var group2offsety = 0.05;
      var multiVector2 = L.polyline(
        [
          [
            [
              this.map.getCenter().lat - 0.2 + group2offsety,
              this.map.getCenter().lng - 0.4 + group2offsetx + 0.15,
            ],
            [
              this.map.getCenter().lat - 0.1 + group2offsety,
              this.map.getCenter().lng - 0.5 + group2offsetx + 0.15,
            ],
            [
              this.map.getCenter().lat + 0.0 + group2offsety,
              this.map.getCenter().lng - 0.4 + group2offsetx + 0.15,
            ],
          ],
          [
            [
              this.map.getCenter().lat + 0.0 + group2offsety,
              this.map.getCenter().lng - 0.5 + group2offsetx + 0.15,
            ],
            [
              this.map.getCenter().lat + 0.1 + group2offsety,
              this.map.getCenter().lng - 0.1 + group2offsetx + 0.15,
            ],
            [
              this.map.getCenter().lat + 0.2 + group2offsety,
              this.map.getCenter().lng - 0.2 + group2offsetx + 0.15,
            ],
            [
              this.map.getCenter().lat + 0.3 + group2offsety,
              this.map.getCenter().lng - 0.6 + group2offsetx + 0.15,
            ],
          ],
        ],
        {
          smoothFactor: 30,
          color: "black",
        }
      )
        .arrowheads({
          size: "10%",
          frequency: "endonly",
        })
        .bindPopup(
          `<pre><code>L.polyline(coords)
  .arrowheads({
    size: '10%',
    frequency: 'endonly'
  });</code></pre>`,
          {
            maxWidth: 2000,
            minWidth: 400,
          }
        );
      multiVector2.addTo(this.map);
    },

    /**
     * 删除
