    deleteFeature() {
      this.drawControl.deleteSelected();
    },

    initDrawControl() {
      this.$nextTick(() => {
        this.drawControl = new DrawControl(this.map);

        this.drawControl.createdFeatureCallback = (drawnFeature) => {
          console.log("画了个layer", drawnFeature);
          setTimeout(() => {
            this.showDescDialog("新增说明", drawnFeature);
          }, 500);
        };

        this.drawControl.selectedFeatureCallback = (drawnFeature) => {
          console.log("选中layer", drawnFeature);
        };

        this.drawControl.updatedFeatureCallback = (drawnFeature) => {
          console.log("更新layer", drawnFeature);
          // let eventId = sessionStorage.getItem("eventId") || null;
          // mappingList({ eventId })
          //   .then((res) => {
