          //   .finally(() => {
          //     let chooseLayer = this.layerArr.filter((layer) => {
          //       let coordinate = JSON.parse(layer.coordinate);
          //       return (
          //         coordinate._leaflet_id === drawnFeature.feature._leaflet_id &&
          //         layer.drawName === drawnFeature.type
          //       );
          //     });
          //     console.log(chooseLayer, "当前选中的图层在数据库中的数据");
          //     this.drawLayersByLayerArr();
          //     this.showDescDialog("修改说明", drawnFeature, chooseLayer);
          //   });
        };
      });
    },

    showDescDialog(title, data, chooseLayer) {
      let passData = { title, data, chooseLayer };
      this.$refs.describeDialog.showDialog(passData);
    },

    getChooseLayer() {
      return this.drawControl.getChooseLayer();
    },

    listenDrawLayers() {
      // this.bus.$off("drawEventLayer");
      // this.bus.$on("drawEventLayer", (eventId) => {
      //   this.getLayers(eventId);
      // });
    },

    getLayers(eventId) {
      // mappingList({ eventId })
      //   .then((res) => {
      //     this.layerArr = res.data;
      //   })
      //   .finally(() => {
      //     this.drawLayersByLayerArr();
      //   });
    },

    drawLayersByLayerArr() {
      console.log(this.layerArr, "通过layerArr回显图层");
      this.layerArr.forEach((item, index) => {
        let row = JSON.parse(item.coordinate);
        if (item.drawName === "marker") {
          const params = {
            point: row._latlng,
            leafletId: row._leaflet_id,
            customObj: { ...row },
            createdFeatureCallback: (e) => {
              console.log("回显点位", e);
            },
          };
          this.drawControl.backMarker(params);
        } else if (item.drawName === "circle") {
          const params = {
            center: [row._latlng.lat, row._latlng.lng],
            radius: row._mRadius,
            leafletId: row._leaflet_id,
            customObj: { ...row },
            createdFeatureCallback: (e) => {
              console.log("回显圆形", e);
            },
          };
          this.drawControl.backCircle(params);
        } else if (item.drawName === "rectangle") {
          const params = {
            points: row._latlngs[0],
            leafletId: row._leaflet_id,
            customObj: { ...row },
            createdFeatureCallback: (e) => {
              console.log("回显矩形", e);
            },
          };
          this.drawControl.backRectangle(params);
        }
      });
    },

