<template>
  <div class="left-let-page">
    <div class="search-box">
      <el-input
        v-model="searchText"
        clearable
        prefix-icon="el-icon-search"
        @input="onInput"
        @clear="onClear"
      />
    </div>

    <div v-if="restaurants.length > 0" class="search-res">
      <div v-for="item in restaurants" :key="item.uid">
        <div @click="choosePlace(item)" class="search-res-item">
          {{ item.name }}
        </div>
      </div>
    </div>

    <div class="btn-box">
      <el-button type="primary" @click="drawingLayers('圆')">圆</el-button>
      <el-button type="primary" @click="drawingLayers('矩形')">矩形</el-button>
      <el-button type="primary" @click="drawingLayers('测试箭头')"
        >测试箭头</el-button
      >
      <el-button type="primary" @click="drawingLayers('箭头')">箭头</el-button>
      <el-button type="primary" @click="drawingLayers('标签')">标签</el-button>
    </div>

    <div id="map"></div>
    <drawingComp ref="drawingComp" :map="map" />
  </div>
</template>
<script>
import "@/utils/leafletMap/tileLayer.baidu.js";
import { debounceFun } from "@/utils/debounceModule";
import drawingComp from "@/components/leafletDrawLayer/drawingComp.vue";

export default {
  components: { drawingComp },
  data() {
    return {
      map: null,
      searchText: null,
      timeout: null,
      restaurants: [],
      marker: null,
      mapIcon: require("@/assets/img/mapIcon/marker.png"),
    };
  },

  methods: {
    /**
     * @Event 方法
     * @description: 初始化地图
     * */
    initMap() {
      this.map = L.map("map", {
        center: [30.74828423874409, 120.73974942949417],
        zoomControl: false, // 縮放按钮
        attributionControl: false, // leaflet map logo
        crs: L.CRS.Baidu,
        zoom: 8,
        minZoom: 4,
        maxZoom: 19,
      });
      L.control
        .zoom({
          position: "bottomright",
        })
        .addTo(this.map);
      L.tileLayer
        .baidu({
          layer: "img3", // 可以在tileLayer.baidu.js中自定义 img、img2、img3、img5、img6、img7、img8
        })
        .addTo(this.map);
      this.map.on("click", this.setMapClick);
    },

    /**
     * @Event 方法
     * @description: 地图点击事件
     * */
    setMapClick(e) {
      var location = {
        name: "",
        location: e.latlng,
      };
      // this.setMarker(location)
      console.log(e, "e");
    },

    /**
     * @Event 方法
     * @description: 输入框搜索事件 防抖
     * */
    onInput: debounceFun(function () {
      let ak = "bOF9gGWXz76q065otbYtWN4A";
      // let url = 'https://api.map.baidu.com/place/v2/suggestion?query=%E6%9D%AD%E5%B7%9E&region=%E4%B8%AD%E5%9B%BD&city_limit=false&output=json&ak=RP0K9NSF8LobjLQgC31d48NNmOfeKRu3'
      let url = `/place/v2/suggestion?query=${this.searchText}&region=中国&city_limit=false&output=json&ak=${ak}`;
      this.$axios.get(url).then((res) => {
        this.restaurants = res.data.result;
      });
    }, 800),

    onClear() {
      this.restaurants = [];
    },

    /**
     * @Event 方法
     * @description: 搜索结果点击
     * */
    choosePlace(item) {
      this.restaurants = [];
      this.setMarker(item);
    },

    setMarker(item) {
      if (this.marker) {
        this.map.removeLayer(this.marker);
      }
      var markerIcon;
      if (item.name) {
        markerIcon = L.divIcon({
          className: "markerBox",
          html:
            `<div class="mapIcon"><img src="${this.mapIcon}" /><span class="markerTips">` +
            item.name +
            "</span></div>",
          iconSize: [32, 32], // marker宽高
          iconAnchor: [28.5, 55], // 文字标注相对位置
        });
      } else {
        markerIcon = L.divIcon({
          className: "markerBox",
          html: `<div class="mapIcon"><img rc="${this.mapIcon}" /><span class="markerTips">未命名定点</span></div>`,
          iconSize: [32, 32], // marker宽高
          iconAnchor: [28.5, 55], // 文字标注相对位置
        });
      }

      const center = L.latLng(item.location.lat, item.location.lng);
      this.map.setView(center);
      this.marker = new L.Marker([item.location.lat, item.location.lng], {
        icon: markerIcon,
      });
      this.map.addLayer(this.marker);
    },

    drawingLayers(name) {
      if (name === "圆") {
        this.$refs.drawingComp.drawCircle();
      } else if (name === "矩形") {
        this.$refs.drawingComp.drawRectangle();
      } else if (name === "箭头") {
        this.$refs.drawingComp.drawArrow();
      } else if (name === "测试箭头") {
        this.$refs.drawingComp.testDrawArrow();
      } else if (name === "标签") {
        this.$refs.drawingComp.drawMarker();
      }
    },
  },

  mounted() {
    this.initMap();
  },
};
</script>
