import { markerIcon } from "@/components/leafletDrawLayer/icon";
import {
  processCoord,
  createDebounce,
} from "@/components/leafletDrawLayer/utils";

let DrawType = {
  marker: "marker",
  polyline: "polyline",
  polygon: "polygon",
  rectangle: "rectangle",
  circle: "circle",
  bufferPolyline: "bufferPolyline",
};

class DrawnFeature {
  type;
  feature;
  customObj; // 添加自定义数据字段

  constructor(feature, type, customObj = null) {
    this.feature = feature;
    this.type = type;
    this.customObj = customObj;
  }
}

class BufferPolyline extends DrawnFeature {
  bufferRadius;
  buffer;

  constructor(bufferRadius, polyline, buffer) {
    super(polyline, DrawType.bufferPolyline);

    this.bufferRadius = bufferRadius;
    this.buffer = buffer;
  }
}

class DrawControl {
  map;

  #drawMarkerControl;
  #drawPolylineControl;
  #drawRectangleControl;
  #drawPolygonControl;
  #drawCircleControl;

  #drawnFeatureMap = new Map();

  #editControl;
  #enableEdit;

  #lastMapCenter;

  #bufferRadius;

  #featurePane;

  selected;

  selectedFeatureCallback;
  createdFeatureCallback;
  updatedFeatureCallback;

  constructor(map) {
    this.map = map;

    //#region tooltip
    L.drawLocal.edit.handlers.remove.tooltip.text = "请点击要删除的图形";

    L.drawLocal.edit.handlers.edit.tooltip.text =
      "●  拖拽节点编辑图形<br />●  点击删除顶点";
    L.drawLocal.edit.handlers.edit.tooltip.subtext = "";

    L.drawLocal.draw.handlers.marker.tooltip.start = "点击地图放置标记";

    L.drawLocal.draw.handlers.polyline.tooltip.start = "点击开始绘制线";
    L.drawLocal.draw.handlers.polyline.tooltip.end = "点击最后一个节点结束画线";
    L.drawLocal.draw.handlers.polyline.tooltip.cont = "点击继续绘制线";

    L.drawLocal.draw.handlers.polygon.tooltip.start = "点击开始绘制多边形";
    L.drawLocal.draw.handlers.polygon.tooltip.end = "点击起点结束绘制多边形";
    L.drawLocal.draw.handlers.polygon.tooltip.cont = "点击继续绘制多边形";

    L.drawLocal.draw.handlers.rectangle.tooltip.start =
      "按下鼠标左键并拖动以绘制矩形";

    L.drawLocal.draw.handlers.circle.tooltip.start =
      "按下鼠标左键并拖动以绘制圆";
    L.drawLocal.draw.handlers.circle.radius = "半径";

    L.drawLocal.draw.handlers.simpleshape.tooltip.end = "松开鼠标结束绘制";
    //#endregion

    let shapeOptions = { weight: 2, color: "#ff0000", opacity: 0.8 };
    // shapeOptions = Object.assign(customObj, shapeOptions);
    this.#drawMarkerControl = new L.Draw.Marker(this.map, { icon: markerIcon });
    this.#drawPolylineControl = new L.Draw.Polyline(this.map, { shapeOptions });
    this.#drawRectangleControl = new L.Draw.Rectangle(this.map, {
      shapeOptions,
      metric: ["km", "m"],
    });
    this.#drawPolygonControl = new L.Draw.Polygon(this.map, {
      shapeOptions,
    });
    this.#drawCircleControl = new L.Draw.Circle(this.map, {
      shapeOptions,
    });

    this.#featurePane = map.createPane(
      "featurePane",
      map.getPane("overlayPane")
    );

    let self = this;
    this.map.on(L.Draw.Event.CREATED, function (event) {
      let drawnFeature;

      if (self.#drawPolylineControl.enabled() && self.#bufferRadius) {
        let buffer = self.#createBuffer(event.layer, self.#bufferRadius);
        drawnFeature = new BufferPolyline(
          self.#bufferRadius,
          event.layer,
          buffer
        );
      } else {
        drawnFeature = new DrawnFeature(
          event.layer,
          event.layerType,
          self.customObj
        );
      }

      self.#drawnFeatureMap.set(event.layer, drawnFeature);

      event.layer.addEventListener("click", function (e) {
        self.#enableEdit = true; // 允许编辑
        if (self.#enableEdit) {
          let drawnFeature = self.#drawnFeatureMap.get(e.target);

          self.#startEdit(e.target);

          console.log(drawnFeature, "drawnFeature");
          self.selected = drawnFeature; // 设置选中的图形【图形实例对象】

          if (self.selectedFeatureCallback)
            self.selectedFeatureCallback(drawnFeature);
        }
      });

      if (self.createdFeatureCallback) {
        self.createdFeatureCallback(drawnFeature);
        // self.createdFeatureCallback = undefined;
      }

      event.layer.options.pane = self.#featurePane;
      self.map.addLayer(event.layer);

      /* 地图空白处点击实现禁用编辑 */
      self.map.addEventListener("click", function (e) {
        if (e.target === self.map) {
          self.stopEdit(); // 调用禁用编辑的方法
        }
      });

      /* 阻止事件冒泡 */
      self.map.eachLayer(function (layer) {
        layer.on("click", function (e) {
          // eslint-disable-next-line no-unused-vars
          e.stop() || e.stopPropagation();
        });
      });
    });
    this.customObj = null;

    this.map.on(L.Draw.Event.EDITED, function (event) {
      let layers = event.layers.getLayers();
      if (layers.length == 0) return;
      let feature = layers[0];
      let drawnFeature = self.#drawnFeatureMap.get(feature);
      if (drawnFeature) {
        if (self.updatedFeatureCallback)
          self.updatedFeatureCallback(drawnFeature);

        self.#updateBuffer(drawnFeature);
      }
    });

    this.map.on(L.Draw.Event.EDITVERTEX, function (event) {
      let feature = event.poly;
      let drawnFeature = self.#drawnFeatureMap.get(feature);

      if (self.updatedFeatureCallback)
        self.updatedFeatureCallback(drawnFeature);

      self.#updateBuffer(drawnFeature);
    });

    let debounce = createDebounce(1000);
    this.map.on(L.Draw.Event.EDITRESIZE, function (event) {
      let feature = event.layer;
      let drawnFeature = self.#drawnFeatureMap.get(feature);

      if (self.updatedFeatureCallback) {
        debounce(() => {
          self.updatedFeatureCallback(drawnFeature);
        });
      }
    });

    this.map.on(L.Draw.Event.EDITMOVE, function (event) {
      let feature = event.layer;
      let drawnFeature = self.#drawnFeatureMap.get(feature);

      if (self.updatedFeatureCallback) {
        debounce(() => {
          self.updatedFeatureCallback(drawnFeature);
        });
      }
    });

    this.map.addEventListener("mousedown", function (e) {
      if (
        self.#drawPolylineControl.enabled() ||
        self.#drawPolygonControl.enabled()
      ) {
        self.#lastMapCenter = self.map.getCenter();
      }
    });

    //绘制线或多边形的同时平移地图的情况
    this.map.addEventListener("mouseup", function (e) {
      if (
        self.#drawPolylineControl.enabled() ||
        self.#drawPolygonControl.enabled()
      ) {
        if (self.#lastMapCenter) {
          let currentMapCenter = self.map.getCenter();
          let points = [];
          points.push([self.#lastMapCenter.lng, self.#lastMapCenter.lat]);
          points.push([currentMapCenter.lng, currentMapCenter.lat]);
          let line = turf.lineString(points);
          var length = turf.length(line, { units: "kilometers" });
          if (length > 0.00001) {
            if (self.#drawPolylineControl.enabled()) {
              self.#drawPolylineControl.deleteLastVertex();
            }
            if (self.#drawPolygonControl.enabled()) {
              self.#drawPolygonControl.deleteLastVertex();
            }
          }
        }
      }
    });
  }

  startEdit() {
    this.#enableEdit = true;
  }

  stopEdit() {
    this.#enableEdit = false;

    this.selected = undefined;

    if (this.#editControl) {
      this.#editControl.disable();
    }
  }

  deleteSelected() {
    if (this.#enableEdit) {
      if (this.selected) {
        this.map.removeLayer(this.selected.feature);
        this.selected.buffer && this.map.removeLayer(this.selected.buffer);
        this.#drawnFeatureMap.delete(this.selected.feature);
      }
    }
  }

  #startEdit(target) {
    if (this.#editControl) {
      this.#editControl.disable();
    }

    if (this.#enableEdit) {
      let featureGroup = new L.featureGroup();
      featureGroup.addLayer(target);

      this.#editControl = new L.EditToolbar.Edit(this.map, {
        featureGroup: featureGroup,
        selectedPathOptions: {
          maintainColor: false,
          color: "#ff0000",
          opacity: 0.8,
        },
      });
      this.#editControl.enable();
    }
  }

  drawMarker(customObj, createdFeatureCallback) {
    this.stopDrawAll();

    if (createdFeatureCallback) {
      this.createdFeatureCallback = createdFeatureCallback;
    }
    this.#drawMarkerControl.enable();
    this.customObj = customObj;
  }

  drawPolyline(customObj, createdFeatureCallback) {
    this.stopDrawAll();

    if (createdFeatureCallback) {
      this.createdFeatureCallback = createdFeatureCallback;
    }
    this.#drawPolylineControl.enable();
    this.customObj = customObj;
  }

  // todo 使用前请先导入/arrowheads/leaflet.geometryutil.js和/arrowheads/leaflet-arrowheads"
  /**
   * 绘制带有箭头的线条
   * @param {Object} customObj - 自定义对象
   * @param {Function} createdFeatureCallback - 创建特征后的回调函数
   * @param {Object} arrowOptions - 箭头选项，例如 { size: '10%', frequency: 'endonly' }
   */
  drawArrowLine(customObj, createdFeatureCallback, arrowOptions) {
    this.stopDrawAll();

    if (createdFeatureCallback) {
      this.createdFeatureCallback = createdFeatureCallback;
    }

    let self = this;
    this.map.on(L.Draw.Event.CREATED, function (event) {
      let drawnFeature;

      if (event.layerType === DrawType.polyline) {
        event.layer.arrowheads(arrowOptions);
      }

      drawnFeature = new DrawnFeature(event.layer, event.layerType, customObj);

      self.#drawnFeatureMap.set(event.layer, drawnFeature);

      event.layer.addEventListener("click", function (e) {
        self.#enableEdit = true; // 允许编辑
        if (self.#enableEdit) {
          let drawnFeature = self.#drawnFeatureMap.get(e.target);

          self.#startEdit(e.target);

          self.selected = drawnFeature; // 设置选中的图形【图形实例对象】

          if (self.selectedFeatureCallback)
            self.selectedFeatureCallback(drawnFeature);
        }
      });

      if (self.createdFeatureCallback) {
        self.createdFeatureCallback(drawnFeature);
      }

      event.layer.options.pane = self.#featurePane;
      self.map.addLayer(event.layer);

      /* 地图空白处点击实现禁用编辑 */
      self.map.addEventListener("click", function (e) {
        if (e.target === self.map) {
          self.stopEdit(); // 调用禁用编辑的方法
        }
      });

      /* 阻止事件冒泡 */
      self.map.eachLayer(function (layer) {
        layer.on("click", function (e) {
          // eslint-disable-next-line no-unused-vars
          e.stop() || e.stopPropagation();
        });
      });
    });

    this.#drawPolylineControl.enable();
    this.customObj = customObj;
  }

  drawBufferPolyline(customObj, bufferRadius, createdFeatureCallback) {
    this.stopDrawAll();

    this.#bufferRadius = bufferRadius;
    if (createdFeatureCallback) {
      this.createdFeatureCallback = createdFeatureCallback;
    }
    this.#drawPolylineControl.enable();
    this.customObj = customObj;
  }

  drawRectangle(customObj, createdFeatureCallback) {
    this.stopDrawAll();

    if (createdFeatureCallback) {
      this.createdFeatureCallback = createdFeatureCallback;
    }
    this.#drawRectangleControl.enable();
    this.customObj = customObj;
  }

  drawPolygon(customObj, createdFeatureCallback) {
    this.stopDrawAll();

    if (createdFeatureCallback) {
      this.createdFeatureCallback = createdFeatureCallback;
    }
    this.#drawPolygonControl.enable();
    this.customObj = customObj;
  }

  drawCircle(customObj, createdFeatureCallback) {
    this.stopDrawAll();

    if (createdFeatureCallback) {
      this.createdFeatureCallback = createdFeatureCallback;
    }
    this.#drawCircleControl.enable();
    this.customObj = customObj;
  }

  stopDrawAll() {
    this.#drawMarkerControl.disable();
    this.#drawPolylineControl.disable();
    this.#drawRectangleControl.disable();
    this.#drawPolygonControl.disable();
    this.#drawCircleControl.disable();
    this.#bufferRadius = undefined;
  }

  #createBuffer(polyline, bufferRadius) {
    let pointArr = [];
    let latlngs = polyline.getLatLngs();
    for (let i = 0; i < latlngs.length; i++) {
      pointArr.push([latlngs[i].lng, latlngs[i].lat]);
    }

    let line = turf.lineString(pointArr);
    let buffered = turf.buffer(line, 0.001 * bufferRadius, {
      units: "kilometers",
      steps: 64,
    }); //线左右两边各50米缓冲区，缓冲区宽共100米

    let polylineBufferPointArr = processCoord(buffered.geometry.coordinates);

    let polylineBuffer = L.polygon(polylineBufferPointArr, {
      stroke: true,
      color: "#ff0000",
      weight: 2,
      fill: true,
      fillColor: "#ff0000",
      fillOpacity: 0.5,
    });
    this.map.addLayer(polylineBuffer);

    let self = this;
    polylineBuffer.addEventListener("click", function (e) {
      if (self.#enableEdit) {
        let line;
        for (let drawnFreature of self.#drawnFeatureMap.values()) {
          if (Object.is(drawnFreature.buffer, e.target)) {
            line = drawnFreature.feature;
            self.selected = drawnFreature;
          }
        }
        if (line) {
          self.#startEdit(line);
        }
      }
    });

    return polylineBuffer;
  }

  #updateBuffer(drawnFreature) {
    if (drawnFreature.type == DrawType.bufferPolyline) {
      this.map.removeLayer(drawnFreature.buffer);

      let buffer = this.#createBuffer(
        drawnFreature.feature,
        drawnFreature.bufferRadius
      );
      drawnFreature.buffer = buffer;
    }
  }

  /* 回显 */
  /**
   * 圆
   * @param: {
   *           center: [28.719674008118904, 120.09066231160989],
   *           radius: 38692.85413975425,
   *           leafletId: 1233,
   *           customObj: {old_leaflet_id: 123},
   *           createdFeatureCallback: (e) => {
   *             console.log("回显圆形", e)
   *           }
   *         }
   * @return:
   * @author: mhf
   * @time: 2024-08-08 16:16:00
   **/
  backCircle(params) {
    let { center, radius, leafletId, customObj, createdFeatureCallback } =
      params;
    this.stopDrawAll();

    if (!center || !radius) {
      console.error("需要中心点和半径来绘制圆形");
      return;
    }

    // 创建圆形图层
    let circle = L.circle(center, {
      radius: radius,
      color: "#ff0000",
      weight: 2,
      fillColor: "#ff0000",
      fillOpacity: 0.5,
    });
    circle._leaflet_id = leafletId; // 回显时带上存储的leafletId

    // 创建 DrawnFeature 对象
    let drawnFeature = new DrawnFeature(circle, DrawType.circle, customObj);

    // 添加到图层管理
    this.#drawnFeatureMap.set(circle, drawnFeature);
    this.map.addLayer(circle);

    // 设置回调
    if (createdFeatureCallback) {
      createdFeatureCallback(drawnFeature);
    }
    // 添加点击事件以启用编辑
    let self = this;
    circle.addEventListener("click", function (e) {
      self.#enableEdit = true; // 允许编辑
      if (self.#enableEdit) {
        let drawnFeature = self.#drawnFeatureMap.get(e.target);

        self.#startEdit(e.target);

        self.selected = drawnFeature; // 设置选中的图形【图形实例对象】

        if (self.selectedFeatureCallback) {
          self.selectedFeatureCallback(drawnFeature);
        }
      }
    });
    this.customObj = customObj;
  }

  /**
   * 多边形
   * @param:
   * @return:
   * @author: mhf
   * @time: 2024-08-08 16:17:36
   **/
  backPolygon(params) {
    let { points, leafletId, customObj, createdFeatureCallback } = params;
    this.stopDrawAll();

    if (!points || points.length < 3) {
      console.error("需要至少三个点位来绘制多边形");
      return;
    }

    // 创建多边形图层
    let polygon = L.polygon(points, {
      color: "#ff0000",
      weight: 2,
      fillColor: "#ff0000",
      fillOpacity: 0.5,
    });
    polygon._leaflet_id = leafletId; // 回显时带上存储的leafletId

    // 创建 DrawnFeature 对象
    let drawnFeature = new DrawnFeature(polygon, DrawType.polygon, customObj);

    // 添加到图层管理
    this.#drawnFeatureMap.set(polygon, drawnFeature);
    this.map.addLayer(polygon);

    // 设置回调
    if (createdFeatureCallback) {
      createdFeatureCallback(drawnFeature);
    }
    // 添加点击事件以启用编辑
    let self = this;
    polygon.addEventListener("click", function (e) {
      self.#enableEdit = true; // 允许编辑
      if (self.#enableEdit) {
        let drawnFeature = self.#drawnFeatureMap.get(e.target);

        self.#startEdit(e.target);

        self.selected = drawnFeature; // 设置选中的图形【图形实例对象】

        if (self.selectedFeatureCallback) {
          self.selectedFeatureCallback(drawnFeature);
        }
      }
    });

    this.customObj = customObj;
  }

  /**
   * 点位标记
   * @param: {
   *           point: {"lat": 28.640433049563354, "lng": 119.76411027223398},
   *           leafletId: 1235,
   *           customObj: {old_leaflet_id: 125},
   *           createdFeatureCallback: (e) => {
   *             console.log("回显点位", e)
   *           }
   *         }
   * @return:
   * @author: mhf
   * @time: 2024-08-08 16:18:31
   **/
  backMarker(params) {
    let { point, leafletId, customObj, createdFeatureCallback } = params;
    this.stopDrawAll();

    if (!point) {
      console.error("需要点位来绘制标记");
      return;
    }

    // 创建标记图层
    let marker = L.marker(point, {
      icon: markerIcon,
    });
    marker._leaflet_id = leafletId; // 回显时带上存储的leafletId

    // 创建 DrawnFeature 对象
    let drawnFeature = new DrawnFeature(marker, DrawType.marker, customObj);

    // 添加到图层管理
    this.#drawnFeatureMap.set(marker, drawnFeature);
    this.map.addLayer(marker);

    // 设置回调
    if (createdFeatureCallback) {
      createdFeatureCallback(drawnFeature);
    }
    // 添加点击事件以启用编辑
    let self = this;
    marker.addEventListener("click", function (e) {
      self.#enableEdit = true; // 允许编辑
      if (self.#enableEdit) {
        let drawnFeature = self.#drawnFeatureMap.get(e.target);

        self.#startEdit(e.target);

        self.selected = drawnFeature; // 设置选中的图形【图形实例对象】

        if (self.selectedFeatureCallback) {
          self.selectedFeatureCallback(drawnFeature);
        }
      }
    });
    this.customObj = customObj;
  }

  /**
   * 矩形
   * @param: {
   *           points: [
   *             {"lat": 28.630433049563354, "lng": 119.76411027223398},
   *             {"lat": 28.82909190082871, "lng": 119.76411027223398},
   *             {"lat": 28.82909190082871, "lng": 120.12975656984503},
   *             {"lat": 28.630433049563354, "lng": 120.12975656984503}
   *           ],
   *           leafletId: 1234,
   *           customObj: {old_leaflet_id: 124},
   *           createdFeatureCallback: (e) => {
   *             console.log("回显矩形", e)
   *           }
   *         }
   * @return:
   * @author: mhf
   * @time: 2024-08-08 16:19:47
   **/
  backRectangle(params) {
    let { points, leafletId, customObj, createdFeatureCallback } = params;
    this.stopDrawAll();

    if (!points || points.length !== 4) {
      console.error("需要四个点位来绘制矩形");
      return;
    }

    // 创建矩形图层
    let rectangle = L.rectangle(points, {
      color: "#ff0000",
      weight: 2,
      fillColor: "#ff0000",
      fillOpacity: 0.5,
    });
    rectangle._leaflet_id = leafletId; // 回显时带上存储的leafletId

    // 创建 DrawnFeature 对象
    let drawnFeature = new DrawnFeature(
      rectangle,
      DrawType.rectangle,
      customObj
    );

    // 添加到图层管理
    this.#drawnFeatureMap.set(rectangle, drawnFeature);
    this.map.addLayer(rectangle);

    // 设置回调
    if (createdFeatureCallback) {
      createdFeatureCallback(drawnFeature);
    }
    // 添加点击事件以启用编辑
    let self = this;
    rectangle.addEventListener("click", function (e) {
      self.#enableEdit = true; // 允许编辑
      if (self.#enableEdit) {
        let drawnFeature = self.#drawnFeatureMap.get(e.target);

        self.#startEdit(e.target);

        self.selected = drawnFeature; // 设置选中的图形【图形实例对象】

        if (self.selectedFeatureCallback) {
          self.selectedFeatureCallback(drawnFeature);
        }
      }
    });
    this.customObj = customObj;
  }

  /**
   * 带箭头的折线
   * @param {Object} params - 参数对象
   * @param {Array} params.coordinates - 线条的经纬度坐标数组
   * @param {Object} params.options - 线条的样式选项
   * @param {Object} params.arrowOptions - 箭头的样式选项
   * @param {Function} params.createdFeatureCallback - 线条创建后的回调函数
   */
  backArrowLine(params) {
    this.stopDrawAll(); // 停止所有绘制

    let {
      coordinates,
      options = {},
      arrowOptions = {},
      createdFeatureCallback,
    } = params;

    if (!coordinates || coordinates.length < 2) {
      console.error("需要至少两个点来绘制折线");
      return;
    }

    // 创建折线
    let polyline = L.polyline(coordinates, options);

    // 添加箭头
    polyline.arrowheads(arrowOptions);

    // 添加到地图
    this.map.addLayer(polyline);

    // 设置回调
    if (createdFeatureCallback) {
      createdFeatureCallback(polyline);
    }

    // 添加点击事件以启用编辑
    polyline.addEventListener("click", (e) => {
      this.#enableEdit = true;
      if (this.#enableEdit) {
        let drawnFeature = new DrawnFeature(polyline, DrawType.polyline);
        this.#drawnFeatureMap.set(polyline, drawnFeature);

        this.#startEdit(polyline);

        this.selected = drawnFeature; // 设置选中的图形【图形实例对象】

        if (this.selectedFeatureCallback) {
          this.selectedFeatureCallback(drawnFeature);
        }
      }
    });

    this.customObj = null;
  }
  /* 回显 */

  /* 删除 */
  deleteFeature(leafletId) {
    if (leafletId) {
      let rectangle = this.#drawnFeatureMap.get(leafletId);
      if (rectangle) {
        this.map.removeLayer(rectangle);
        this.#drawnFeatureMap.delete(leafletId);
        this.#enableEdit = false;
        this.selected = null;
      }
    } else {
      console.error("需要传入leafletId");
    }
  }
}

export { DrawControl, DrawType };
